use dots_model::EnvSpec;

use crate::EnvError;
use crate::collect::{Contribution, EnvCtx, EnvOverlay};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Shell {
    Zsh,
    Bash,
    Fish,
    PowerShell,
}

impl Shell {
    pub const ALL: [Shell; 3] = [Shell::Zsh, Shell::Fish, Shell::PowerShell];

    /// The generated file's extension: `sh`, `fish` or `ps1`.
    pub fn ext(self) -> &'static str {
        match self {
            Shell::Zsh | Shell::Bash => "sh",
            Shell::Fish => "fish",
            Shell::PowerShell => "ps1",
        }
    }

    /// From a `$SHELL`-style path or name.
    pub fn detect(shell: &str) -> Option<Shell> {
        let name = shell.rsplit(['/', '\\']).next()?.trim_end_matches(".exe");
        match name {
            "zsh" => Some(Shell::Zsh),
            "bash" | "sh" => Some(Shell::Bash),
            "fish" => Some(Shell::Fish),
            "pwsh" | "powershell" => Some(Shell::PowerShell),
            _ => None,
        }
    }
}

/// The three generated files.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EnvFiles {
    pub sh: String,
    pub fish: String,
    pub ps1: String,
}

impl EnvFiles {
    pub fn get(&self, shell: Shell) -> &str {
        match shell {
            Shell::Zsh | Shell::Bash => &self.sh,
            Shell::Fish => &self.fish,
            Shell::PowerShell => &self.ps1,
        }
    }
}

/// Generate the three env files. Deterministic: same input, same bytes.
pub fn generate(contribs: &[Contribution], ctx: &EnvCtx) -> Result<EnvFiles, EnvError> {
    let specs: Vec<&EnvSpec> = contribs.iter().map(|c| &c.spec).collect();
    for s in &specs {
        for k in s.vars.keys() {
            if !valid_name(k) {
                return Err(EnvError::BadVarName(k.clone()));
            }
        }
    }
    let mut o = EnvOverlay::new(ctx.clone());
    for s in specs {
        o.add_package(s);
    }
    let home = ctx.home.to_string_lossy().into_owned();
    let path = o.path_entries();
    let vars: Vec<(&String, &String)> = o
        .vars()
        .iter()
        .filter(|(k, _)| k.as_str() != "PATH")
        .collect();
    let sources = o.sources();
    Ok(EnvFiles {
        sh: sh(&home, &path, &vars, sources),
        fish: fish(&home, &path, &vars, sources),
        ps1: ps1(&home, &path, &vars, sources),
    })
}

fn valid_name(n: &str) -> bool {
    let mut c = n.chars();
    c.next()
        .is_some_and(|f| f.is_ascii_alphabetic() || f == '_')
        && c.all(|f| f.is_ascii_alphanumeric() || f == '_')
}

const HEADER: &str = "# Generated by dots. Do not edit; changes are overwritten.\n";

/// The part of a path after `$HOME`, with `/` separators: every shell (Git Bash included)
/// reads them, and a joined path can mix both kinds on Windows. A no-op off Windows, where a
/// backslash is a legal file-name character.
pub(crate) fn home_relative(rest: &str) -> std::borrow::Cow<'_, str> {
    if cfg!(windows) {
        std::borrow::Cow::Owned(rest.replace('\\', "/"))
    } else {
        std::borrow::Cow::Borrowed(rest)
    }
}

/// Double-quote `s`, escaping what the shell would interpret, and keep a leading home dir
/// portable as `$HOME`.
fn quote(s: &str, home: &str, esc: &[char], esc_with: char) -> String {
    let (prefix, rest) = match s.strip_prefix(home) {
        Some(r)
            if !home.is_empty() && (r.is_empty() || r.starts_with('/') || r.starts_with('\\')) =>
        {
            ("$HOME", r)
        }
        _ => ("", s),
    };
    let mut out = String::from("\"");
    out.push_str(prefix);
    let rest = if prefix.is_empty() {
        std::borrow::Cow::Borrowed(rest)
    } else {
        home_relative(rest)
    };
    for ch in rest.chars() {
        if esc.contains(&ch) {
            out.push(esc_with);
        }
        out.push(ch);
    }
    out.push('"');
    out
}

fn q_sh(s: &str, home: &str) -> String {
    quote(s, home, &['\\', '"', '$', '`'], '\\')
}
fn q_fish(s: &str, home: &str) -> String {
    quote(s, home, &['\\', '"', '$'], '\\')
}
fn q_ps(s: &str, home: &str) -> String {
    quote(s, home, &['`', '"', '$'], '`')
}

type Vars<'a> = [(&'a String, &'a String)];

fn sh(home: &str, path: &[String], vars: &Vars, sources: &[String]) -> String {
    let mut o = String::from(HEADER);
    if !path.is_empty() {
        o.push_str("__dots_path() {\n  case \":$PATH:\" in\n    *\":$1:\"*) ;;\n    *) PATH=\"$1:$PATH\" ;;\n  esac\n}\n");
        for p in path.iter().rev() {
            o.push_str(&format!("__dots_path {}\n", q_sh(p, home)));
        }
        o.push_str("unset -f __dots_path\nexport PATH\n");
    }
    for (k, v) in vars {
        o.push_str(&format!("export {k}={}\n", q_sh(v, home)));
    }
    for s in sources
        .iter()
        .filter(|s| !s.ends_with(".fish") && !s.ends_with(".ps1"))
    {
        let q = q_sh(s, home);
        o.push_str(&format!("[ -f {q} ] && . {q}\n"));
    }
    o
}

fn fish(home: &str, path: &[String], vars: &Vars, sources: &[String]) -> String {
    let mut o = String::from(HEADER);
    for p in path.iter().rev() {
        let q = q_fish(p, home);
        o.push_str(&format!(
            "contains -- {q} $PATH; or set -gx PATH {q} $PATH\n"
        ));
    }
    for (k, v) in vars {
        o.push_str(&format!("set -gx {k} {}\n", q_fish(v, home)));
    }
    for s in sources.iter().filter(|s| s.ends_with(".fish")) {
        let q = q_fish(s, home);
        o.push_str(&format!("test -f {q}; and source {q}\n"));
    }
    o
}

fn ps1(home: &str, path: &[String], vars: &Vars, sources: &[String]) -> String {
    let mut o = String::from(HEADER);
    for p in path.iter().rev() {
        let q = q_ps(p, home);
        o.push_str(&format!(
            "if (($env:PATH -split [IO.Path]::PathSeparator) -notcontains {q}) {{ $env:PATH = {q} + [IO.Path]::PathSeparator + $env:PATH }}\n"
        ));
    }
    for (k, v) in vars {
        o.push_str(&format!("$env:{k} = {}\n", q_ps(v, home)));
    }
    for s in sources.iter().filter(|s| s.ends_with(".ps1")) {
        let q = q_ps(s, home);
        o.push_str(&format!("if (Test-Path {q}) {{ . {q} }}\n"));
    }
    o
}
